  --color-border: #d1d5e0;
  --color-border-focus: #5b6af0;
  --color-error: #c0392b;
  --color-error-bg: #fdf3f2;
  --color-error-border: #e88080;
  --color-success: #1a7a4a;
  --color-success-bg: #edfaf3;
  --color-success-border: #6fcfa0;
  --color-required: #c0392b;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --shadow-card: 0 4px 24px rgba(0, 0, 0, 0.08);
  --font-sans: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
