.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ── Layout container ── */
.container {
  width: min(100%, 560px);
  margin-inline: auto;
  padding-inline: 1.25rem;
}

/* ── Header ── */
.site-header {
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
}

.site-header .container {
  width: min(100%, 1200px);
  display: flex;
  align-items: center;
  gap: 0.625rem;
  padding-block: 1rem;
}

.site-logo {
  font-size: 1.5rem;
  color: var(--color-brand);
}

.site-name {
  font-size: 1.125rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--color-text);
}

/* ── Main content ── */
.main-content {
  flex: 1;
  padding-block: 3rem;
}

/* ── Form card ── */
.form-card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 2.5rem;
}

.form-card__header {
  margin-bottom: 2rem;
}

.form-card__header h1 {
  font-size: 1.75rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.2;
  margin-bottom: 0.5rem;
}

.form-card__subtitle {
  color: var(--color-text-muted);
  font-size: 0.9375rem;
}

/* ── Required note ── */
.required-note {
  font-size: 0.875rem;
  color: var(--color-text-muted);
  margin-bottom: 1.75rem;
}

/* ── Form fields ── */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  margin-bottom: 1.5rem;
}

label {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--color-text);
}

.required-star {
  color: var(--color-required);
  margin-left: 0.125rem;
}

.optional-label {
  font-weight: 400;
  color: var(--color-text-muted);
  font-size: 0.875rem;
}

input[type="text"],
input[type="email"],
input[type="tel"] {
  width: 100%;
  padding: 0.625rem 0.875rem;
  font-family: inherit;
  font-size: 1rem;
  color: var(--color-text);
  background: var(--color-surface);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-sm);
  transition: border-color var(--transition), box-shadow var(--transition);
  outline: none;
  min-height: 44px; /* touch target */
}

input[type="text"]:hover,
input[type="email"]:hover,
input[type="tel"]:hover {
  border-color: #a0a8d0;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus {
  border-color: var(--color-border-focus);
  box-shadow: 0 0 0 3px rgba(91, 106, 240, 0.2);
}

/* Invalid state */
input[aria-invalid="true"] {
  border-color: var(--color-error-border);
  background-color: var(--color-error-bg);
}

input[aria-invalid="true"]:focus {
  border-color: var(--color-error);
  box-shadow: 0 0 0 3px rgba(192, 57, 43, 0.18);
}

/* ── Help text ── */
.field-help {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  line-height: 1.5;
}

/* ── Error text ── */
.field-error {
  font-size: 0.875rem;
  color: var(--color-error);
  font-weight: 500;
  line-height: 1.4;
}

.field-error[hidden] {
  display: none;
}

/* ── Submit button ── */
.form-actions {
  margin-top: 2rem;
}

.btn-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-height: 48px;
  padding: 0.75rem 1.5rem;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  color: #fff;
  background-color: var(--color-brand);
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background-color var(--transition), box-shadow var(--transition);
  letter-spacing: 0.01em;
}

.btn-submit:hover {
  background-color: var(--color-brand-hover);
}

.btn-submit:active {
  background-color: var(--color-brand-active);
}

.btn-submit:focus-visible {
  outline: 3px solid var(--color-brand);
  outline-offset: 3px;
  box-shadow: 0 0 0 5px rgba(91, 106, 240, 0.25);
}

/* ── Success panel ── */
.success-panel {
  text-align: center;
  padding: 2rem 1rem;
}

.success-panel[hidden] {
  display: none;
}

.success-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 3.5rem;
  height: 3.5rem;
  background-color: var(--color-success-bg);
  border: 2px solid var(--color-success-border);
  border-radius: 50%;
  font-size: 1.5rem;
  color: var(--color-success);
  margin-bottom: 1.25rem;
}

.success-panel h2 {
  font-size: 1.5rem;
  font-weight: 800;
  margin-bottom: 0.5rem;
}

.success-panel p {
  color: var(--color-text-muted);
}

/* ── Footer ── */
.site-footer {
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  padding-block: 1.25rem;
}

.site-footer .container {
  width: min(100%, 1200px);
}

.site-footer p {
  font-size: 0.875rem;
  color: var(--color-text-muted);
  text-align: center;
}

/* ── Reflow: narrow viewports ── */
@media (max-width: 400px) {
  .form-card {
    padding: 1.5rem 1.25rem;
  }

  .form-card__header h1 {
    font-size: 1.375rem;
  }
}

/* ── Reduced motion ── */
@media (prefers-reduced-motion: reduce) {
  *,
