const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

const dir = '/workspace/sandbox/skills/building-accessible-ui/simple-contact-form--framework-vanilla-js--style-modern--validation-message-absent/claude-sonnet-4.6__s2/';
const html = fs.readFileSync(dir + 'index.html', 'utf8');

// Inline CSS and JS for self-contained page evaluation
const css = fs.readFileSync(dir + 'styles.css', 'utf8');
const js  = fs.readFileSync(dir + 'main.js', 'utf8');

// Patch HTML to inline resources
const patched = html
  .replace('<link rel="stylesheet" href="styles.css" />', `<style>${css}</style>`)
  .replace('<script src="main.js"></script>', `<script>${js}</script>`);

(async () => {
  const b = await chromium.launch();

  async function runAxe(page, label) {
    await page.addScriptTag({ path: '/tmp/axe.min.js' });
    const r = await page.evaluate(async () => await window.axe.run());
    const wcag = r.violations.filter(v => !v.tags.includes('best-practice'));
    const bp   = r.violations.filter(v =>  v.tags.includes('best-practice'));
    console.log(`\n=== ${label} ===`);
