      wcag: wcag.map(v => ({ id: v.id, impact: v.impact, nodes: v.nodes.map(n => ({ target: n.target, failureSummary: n.failureSummary })) })),
      bp:   bp.map(v   => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
    }, null, 2));
    return wcag.length;
  }

  // --- Test 1: initial state ---
  const p1 = await b.newPage();
  await p1.setContent(patched, { waitUntil: 'load' });
  const e1 = await runAxe(p1, 'Initial state');

  // --- Test 2: post-submit error state ---
  const p2 = await b.newPage();
  await p2.setContent(patched, { waitUntil: 'load' });
  await p2.click('button[type="submit"]');
  await p2.waitForTimeout(300);
  const e2 = await runAxe(p2, 'Post-submit (error) state');

  // --- Test 3: success state ---
  const p3 = await b.newPage();
  await p3.setContent(patched, { waitUntil: 'load' });
  await p3.fill('#full-name', 'Jane Doe');
  await p3.fill('#email', 'jane@example.com');
  await p3.click('button[type="submit"]');
  await p3.waitForTimeout(300);
  const e3 = await runAxe(p3, 'Success state');

  await b.close();
  process.exit((e1 + e2 + e3) > 0 ? 1 : 0);
})();
