const { chromium } = require('playwright');
const fs = require('fs');

const dir = '/workspace/sandbox/skills/building-accessible-ui/simple-contact-form--framework-vanilla-js--style-modern--validation-message-absent/claude-sonnet-4.6__s2/';
const html = fs.readFileSync(dir + 'index.html', 'utf8');
const css  = fs.readFileSync(dir + 'styles.css', 'utf8');
const js   = fs.readFileSync(dir + 'main.js', 'utf8');

const patched = html
  .replace('<link rel="stylesheet" href="styles.css" />', `<style>${css}</style>`)
  .replace('<script src="main.js"></script>', `<script>${js}</script>`);

(async () => {
  const b = await chromium.launch();

  async function runAxe(page, label) {
    await page.addScriptTag({ path: '/tmp/axe.min.js' });
    const r = await page.evaluate(async () => await window.axe.run());
    const wcag = r.violations.filter(v => !v.tags.includes('best-practice'));
    const bp   = r.violations.filter(v =>  v.tags.includes('best-practice'));
    console.log(`\n=== ${label} ===`);
    console.log(JSON.stringify({
      wcag: wcag.map(v => ({ id: v.id, impact: v.impact, nodes: v.nodes.map(n => ({ target: n.target, failureSummary: n.failureSummary })) })),
      bp:   bp.map(v   => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
    }, null, 2));
    return wcag.length;
  }

  const p1 = await b.newPage();
  await p1.setContent(patched, { waitUntil: 'load' });
  const e1 = await runAxe(p1, 'Initial state');

  const p2 = await b.newPage();
  await p2.setContent(patched, { waitUntil: 'load' });
  await p2.click('button[type="submit"]');
  await p2.waitForTimeout(300);
  const e2 = await runAxe(p2, 'Post-submit (error) state');

  const p3 = await b.newPage();
  await p3.setContent(patched, { waitUntil: 'load' });
  await p3.fill('#full-name', 'Jane Doe');
  await p3.fill('#email', 'jane@example.com');
  await p3.click('button[type="submit"]');
  await p3.waitForTimeout(300);
  const e3 = await runAxe(p3, 'Success state');

  await b.close();
  const total = e1 + e2 + e3;
  console.log(`\nTotal WCAG violations: ${total}`);
  process.exit(total > 0 ? 1 : 0);
})();
